// ---------------------------------------------------------------------------
// Minimal COM smart pointer (kept dependency-free rather than relying on
// <wrl/client.h>, which isn't reliably available in this MinGW toolchain).
// ---------------------------------------------------------------------------
template <typename T> struct ComPtr {
  T *ptr = nullptr;
  ComPtr() = default;
  ComPtr(T *p) : ptr(p) {
    if (ptr)
      ptr->AddRef();
  }
  ComPtr(const ComPtr &other) {
    ptr = other.ptr;
    if (ptr)
      ptr->AddRef();
  }
  ComPtr(ComPtr &&other) noexcept : ptr(other.ptr) { other.ptr = nullptr; }
  ComPtr &operator=(T *p) {
    if (ptr != p) {
      Reset();
      ptr = p;
      if (ptr)
        ptr->AddRef();
    }
    return *this;
  }
  ComPtr &operator=(const ComPtr &other) {
    if (this != &other) {
      Reset();
      ptr = other.ptr;
      if (ptr)
        ptr->AddRef();
    }
    return *this;
  }
  ComPtr &operator=(ComPtr &&other) noexcept {
    if (this != &other) {
      Reset();
      ptr = other.ptr;
      other.ptr = nullptr;
    }
    return *this;
  }
  ~ComPtr() { Reset(); }
  void Reset() {
    if (ptr) {
      ptr->Release();
      ptr = nullptr;
    }
  }
  T **operator&() {
    // Prevent leaks: release any existing object before handing out the
    // raw pointer for a COM creation call to overwrite.
    Reset();
    return &ptr;
  }
  T *operator->() const { return ptr; }
  T *Get() const { return ptr; }
  operator T *() const { return ptr; }
};

