// ----------------------------------------------------------------------------
// Rolling Ring Buffer (History & Histogram Calculation)
// Fixed-capacity circular buffer avoiding dynamic allocations during rendering.
// ----------------------------------------------------------------------------
template <size_t Capacity> class RollingHistory {
public:
  float values[Capacity] = {};
  size_t count = 0;
  size_t head = 0;

  void Record(float v) {
    values[head] = v;
    head = (head + 1) % Capacity;
    if (count < Capacity) {
      count++;
    }
  }

  void Reset() {
    count = 0;
    head = 0;
  }

  float GetAverage() const {
    if (count == 0)
      return 0.0f;
    double sum = 0.0;
    for (size_t i = 0; i < count; ++i) {
      sum += values[i];
    }
    return static_cast<float>(sum / count);
  }

  float GetMin() const {
    if (count == 0)
      return 0.0f;
    float m = values[0];
    for (size_t i = 1; i < count; ++i) {
      if (values[i] < m)
        m = values[i];
    }
    return m;
  }

  float GetMax() const {
    if (count == 0)
      return 0.0f;
    float m = values[0];
    for (size_t i = 1; i < count; ++i) {
      if (values[i] > m)
        m = values[i];
    }
    return m;
  }

  // Computes statistical percentile (0.0 to 1.0, e.g. 0.95 for 95th percentile).
  // Uses std::nth_element on a vector copy when count > 0 to avoid locking or
  // mutating the live buffer, using O(N) average time without fixed capacity stack allocation.
  float GetPercentile(float p) const {
    if (count == 0)
      return 0.0f;
    if (count == 1)
      return values[0];

    std::vector<float> temp(values, values + count);
    size_t idx = static_cast<size_t>(p * (count - 1));
    if (idx >= count)
      idx = count - 1;
    std::nth_element(temp.begin(), temp.begin() + idx, temp.end());
    return temp[idx];
  }

  // Computes two statistical percentiles in a single sorting pass to avoid
  // duplicate sorting overhead when querying both P95 and P99 simultaneously.
  void GetSortedPercentiles(float p1, float p2, float &out1, float &out2) const {
    if (count == 0) {
      out1 = 0.0f;
      out2 = 0.0f;
      return;
    }
    if (count == 1) {
      out1 = values[0];
      out2 = values[0];
      return;
    }

    std::vector<float> temp(values, values + count);
    std::sort(temp.begin(), temp.end());
    size_t idx1 = static_cast<size_t>(p1 * (count - 1));
    if (idx1 >= count)
      idx1 = count - 1;
    size_t idx2 = static_cast<size_t>(p2 * (count - 1));
    if (idx2 >= count)
      idx2 = count - 1;
    out1 = temp[idx1];
    out2 = temp[idx2];
  }
};

// ----------------------------------------------------------------------------
// Section Timer for Code Brackets
// Tracks high-precision execution metrics across individual code sections.
// ----------------------------------------------------------------------------
struct SectionTimer {
  LONGLONG totalTicks = 0;
  LONGLONG lastTicks = 0;
  LONGLONG minTicks = LLONG_MAX;
  LONGLONG maxTicks = 0;
  UINT64 callCount = 0;

  void RecordTicks(LONGLONG ticks) {
    totalTicks += ticks;
    lastTicks = ticks;
    if (ticks < minTicks)
      minTicks = ticks;
    if (ticks > maxTicks)
      maxTicks = ticks;
    callCount++;
  }

  void Reset() {
    totalTicks = 0;
    lastTicks = 0;
    minTicks = LLONG_MAX;
    maxTicks = 0;
    callCount = 0;
  }
};

